mapper.delete:
delete from
favorite where match_id=#{matchId} and user_id=#{userId} and
match_type=#{matchType}

mapper.select:
SELECT COUNT(*) FROM ( SELECT 'Personal' AS matchType, m.personal_match_id AS matchId, m.sport, m.status, m.match_date AS matchDate FROM favorite f JOIN personal_match m ON m.personal_match_id = f.match_id WHERE f.user_id = #{userId} AND f.match_type = 'Personal'
UNION ALL
SELECT 'Team' AS matchType, m.team_match_id AS matchId, m.sport, m.status, m.match_date AS matchDate FROM favorite f JOIN team_match m ON m.team_match_id = f.match_id WHERE f.user_id = #{userId} AND f.match_type = 'Team' ) t WHERE 1 = 1 AND t.sport = #{sport} AND t.status = #{status} AND t.matchDate >= #{startDate} AND t.matchDate <= #{endDate}
